// Builds columns BF (Row Key) and BG (Size Tier) for the header + every data row.
try {
  var res = $input.first().json;
  var rows = res.values || [];
  if (rows.length < 2) { return [{ json: { _error: 'No data rows' } }]; }

  var header = rows[0];
  var body = rows.slice(1);
  var iCert = header.indexOf('MCS Cert Number');
  var iRev = header.indexOf('Review Count');
  var iSite = header.indexOf('Website');
  var iPhone = header.indexOf('Phone');
  var iName = header.indexOf('Company Name');
  if (iCert === -1 || iRev === -1) {
    return [{ json: { _error: 'Required headers not found' } }];
  }

  function domainOf(w) {
    var d = String(w || '').toLowerCase().trim();
    if (!d) { return ''; }
    if (d.indexOf('://') !== -1) { d = d.split('://')[1]; }
    if (d.indexOf('www.') === 0) { d = d.substring(4); }
    return d.split('/')[0].split('?')[0].trim();
  }
  function sizeTier(rv) {
    // Blank Review Count means no Google data was ever fetched for this lead.
    if (rv === undefined || rv === null || String(rv) === '') { return '0 - unknown'; }
    var n = Number(rv) || 0;
    if (n >= 500) { return '6 - 500+'; }
    if (n >= 150) { return '5 - 150-499'; }
    if (n >= 50) { return '4 - 50-149'; }
    if (n >= 15) { return '3 - 15-49'; }
    if (n >= 5) { return '2 - 5-14'; }
    return '1 - 0-4';
  }

  var values = [['Row Key', 'Size Tier']];
  var keys = {}, dupKeys = 0, tiers = {}, byCert = 0, byDom = 0, byTel = 0, byName = 0;

  for (var i = 0; i < body.length; i++) {
    var r = body[i] || [];
    var cert = String(r[iCert] || '').trim();
    var key = '';
    if (cert) { key = 'MCS:' + cert; byCert++; }
    else {
      var dm = domainOf(r[iSite]);
      if (dm) { key = 'DOM:' + dm; byDom++; }
      else if (String(r[iPhone] || '')) { key = 'TEL:' + String(r[iPhone]); byTel++; }
      else { key = 'NAME:' + String(r[iName] || '').toLowerCase().replace(/[^a-z0-9]/g, '').substring(0, 40); byName++; }
    }
    if (keys[key]) { dupKeys++; } else { keys[key] = true; }

    var tier = sizeTier(r[iRev]);
    tiers[tier] = (tiers[tier] || 0) + 1;
    values.push([key, tier]);
  }

  return [{ json: {
    range: "'Outreach CRM'!BF1:BG" + (body.length + 1),
    rowsWritten: values.length,
    dataRows: body.length,
    uniqueKeys: Object.keys(keys).length,
    duplicateKeys: dupKeys,
    keySource: { cert: byCert, domain: byDom, phone: byTel, name: byName },
    tierCounts: tiers,
    values: values
  }}];
} catch (e) {
  return [{ json: { _error: 'Build Columns failed: ' + e.message } }];
}

try {
  var plan = $('🧮 Build Columns').first().json;
  var res = $input.first().json || {};
  return [{ json: {
    updatedRange: res.updatedRange || null,
    updatedCells: res.updatedCells || 0,
    dataRows: plan.dataRows,
    uniqueKeys: plan.uniqueKeys,
    duplicateKeys: plan.duplicateKeys,
    keySource: plan.keySource,
    tierCounts: plan.tierCounts
  }}];
} catch (e) {
  return [{ json: { _error: 'Summary failed: ' + e.message } }];
}
